218			IdentifierFilter: identityProvider.IdentifierFilter,
219			Type:             storepb.IdentityProvider_Type(storepb.IdentityProvider_Type_value[identityProvider.Type.String()]),
220			Config:           convertIdentityProviderConfigToStore(identityProvider.Type, identityProvider.Config),
221		}
222		return temp
223	}
