227			oauth2Config := config.GetOauth2Config()
228			return &storepb.IdentityProviderConfig{
229				Config: &storepb.IdentityProviderConfig_Oauth2Config{
230					Oauth2Config: &storepb.OAuth2Config{
231						ClientId:     oauth2Config.ClientId,
